pragma solidity ^0.8.19;

library EllipticCurve {
    uint256 constant P = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F;
    uint256 constant A = 0;
    uint256 constant B = 7;
    uint256 constant GX = 0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798;
    uint256 constant GY = 0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8;
    uint256 constant N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;

    struct Point {
        uint256 x;
        uint256 y;
    }

    function isOnCurve(Point memory p) internal pure returns (bool) {
        if (p.x == 0 && p.y == 0) return true; // point at infinity
        uint256 lhs = mulmod(p.y, p.y, P);
        uint256 rhs = addmod(mulmod(mulmod(p.x, p.x, P), p.x, P), B, P);
        return lhs == rhs;
    }

    function pointAdd(Point memory p1, Point memory p2) internal pure returns (Point memory) {
        if (p1.x == 0 && p1.y == 0) return p2;
        if (p2.x == 0 && p2.y == 0) return p1;
        if (p1.x == p2.x && p1.y != p2.y) return Point(0, 0);

        uint256 lambda;
        if (p1.x == p2.x && p1.y == p2.y) {
            lambda = mulmod(mulmod(3, mulmod(p1.x, p1.x, P), P), _modInverse(mulmod(2, p1.y, P), P), P);
        } else {
            uint256 dy = addmod(p2.y, P - p1.y, P);
            uint256 dx = addmod(p2.x, P - p1.x, P);
            lambda = mulmod(dy, _modInverse(dx, P), P);
        }

        uint256 x3 = addmod(mulmod(lambda, lambda, P), P - addmod(p1.x, p2.x, P), P);
        uint256 y3 = addmod(mulmod(lambda, addmod(p1.x, P - x3, P), P), P - p1.y, P);
        return Point(x3, y3);
    }

    function scalarMul(Point memory p, uint256 k) internal pure returns (Point memory) {
        Point memory result = Point(0, 0);
        Point memory current = p;
        while (k > 0) {
            if (k & 1 == 1) {
                result = pointAdd(result, current);
            }
            current = pointAdd(current, current);
            k >>= 1;
        }
        return result;
    }

    function _modInverse(uint256 a, uint256 m) internal pure returns (uint256) {
        return _modExp(a, m - 2, m);
    }

    function _modExp(uint256 base, uint256 exp, uint256 mod) internal pure returns (uint256 result) {
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x20)
            mstore(add(ptr, 0x20), 0x20)
            mstore(add(ptr, 0x40), 0x20)
            mstore(add(ptr, 0x60), base)
            mstore(add(ptr, 0x80), exp)
            mstore(add(ptr, 0xa0), mod)
            if iszero(staticcall(gas(), 0x05, ptr, 0xc0, ptr, 0x20)) { revert(0, 0) }
            result := mload(ptr)
        }
    }
}

contract MultiTenantKeyRegistry {
    using EllipticCurve for EllipticCurve.Point;

    struct TenantKeySlot {
        bytes32 keyHash;
        uint64 registeredAt;
        uint64 expiresAt;
        uint8 keyType; // 1 = ECDSA, 2 = Schnorr, 3 = BLS
        bool active;
    }

    struct VerificationContext {
        uint256 tenantId;
        bytes32 messageHash;
        uint8 sigType;
    }

    mapping(uint256 => mapping(bytes32 => TenantKeySlot)) private _tenantKeys;
    mapping(uint256 => address) private _tenantAdmins;
    mapping(uint256 => uint256) private _tenantNonces;

    event KeyRegistered(uint256 indexed tenantId, bytes32 indexed keyId, uint8 keyType);
    event SignatureVerified(uint256 indexed tenantId, bytes32 indexed messageHash);

    modifier onlyTenantAdmin(uint256 tenantId) {
        require(_tenantAdmins[tenantId] == msg.sender, "Not tenant admin");
        _;
    }

    function initializeTenant(uint256 tenantId) external {
        require(_tenantAdmins[tenantId] == address(0), "Already initialized");
        _tenantAdmins[tenantId] = msg.sender;
    }

    function registerKey(
        uint256 tenantId,
        bytes32 keyId,
        uint8 keyType,
        uint256 pubKeyX,
        uint256 pubKeyY,
        uint64 ttl
    ) external onlyTenantAdmin(tenantId) {
        require(keyType >= 1 && keyType <= 3, "Invalid key type");
        EllipticCurve.Point memory pubKey = EllipticCurve.Point(pubKeyX, pubKeyY);
        require(EllipticCurve.isOnCurve(pubKey), "Key not on curve");

        // Use abi.encode (not encodePacked) to prevent type confusion via collision
        bytes32 keyHash = keccak256(abi.encode(tenantId, pubKeyX, pubKeyY, keyType));
        _tenantKeys[tenantId][keyId] = TenantKeySlot({
            keyHash: keyHash,
            registeredAt: uint64(block.timestamp),
            expiresAt: uint64(block.timestamp) + ttl,
            keyType: keyType,
            active: true
        });
        emit KeyRegistered(tenantId, keyId, keyType);
    }

    function verifySignature(
        uint256 tenantId,
        bytes32 keyId,
        bytes32 messageHash,
        uint256 r,
        uint256 s,
        uint256 pubKeyX,
        uint256 pubKeyY
    ) external returns (bool) {
        TenantKeySlot storage slot = _tenantKeys[tenantId][keyId];
        require(slot.active, "Key not active");
        require(block.timestamp < slot.expiresAt, "Key expired");

        // Reconstruct key hash with tenant binding using abi.encode
        bytes32 computedHash = keccak256(abi.encode(tenantId, pubKeyX, pubKeyY, slot.keyType));
        require(computedHash == slot.keyHash, "Key mismatch");

        VerificationContext memory ctx = VerificationContext({
            tenantId: tenantId,
            messageHash: messageHash,
            sigType: slot.keyType
        });

        bool valid = _dispatchVerification(ctx, r, s, pubKeyX, pubKeyY);
        if (valid) {
            _tenantNonces[tenantId]++;
            emit SignatureVerified(tenantId, messageHash);
        }
        return valid;
    }

    function _dispatchVerification(
        VerificationContext memory ctx,
        uint256 r,
        uint256 s,
        uint256 pubKeyX,
        uint256 pubKeyY
    ) internal pure returns (bool) {
        if (ctx.sigType == 1) {
            return _verifyECDSA(ctx.messageHash, r, s, pubKeyX, pubKeyY);
        } else if (ctx.sigType == 2) {
            return _verifySchnorr(ctx.messageHash, r, s, pubKeyX, pubKeyY);
        }
        return false;
    }

    function _verifyECDSA(
        bytes32 msgHash,
        uint256 r,
        uint256 s,
        uint256 pubKeyX,
        uint256 pubKeyY
    ) internal pure returns (bool) {
        require(r > 0 && r < EllipticCurve.N, "Invalid r");
        require(s > 0 && s < EllipticCurve.N, "Invalid s");

        uint256 sInv = EllipticCurve._modInverse(s, EllipticCurve.N);
        uint256 u1 = mulmod(uint256(msgHash), sInv, EllipticCurve.N);
        uint256 u2 = mulmod(r, sInv, EllipticCurve.N);

        EllipticCurve.Point memory G = EllipticCurve.Point(EllipticCurve.GX, EllipticCurve.GY);
        EllipticCurve.Point memory Q = EllipticCurve.Point(pubKeyX, pubKeyY);

        EllipticCurve.Point memory p1 = EllipticCurve.scalarMul(G, u1);
        EllipticCurve.Point memory p2 = EllipticCurve.scalarMul(Q, u2);
        EllipticCurve.Point memory R = EllipticCurve.pointAdd(p1, p2);

        return R.x == r;
    }

    function _verifySchnorr(
        bytes32 msgHash,
        uint256 r,
        uint256 s,
        uint256 pubKeyX,
        uint256 pubKeyY
    ) internal pure returns (bool) {
        require(s > 0 && s < EllipticCurve.N, "Invalid s");

        // Domain-separated challenge with explicit scheme identifier
        bytes32 challenge = keccak256(abi.encode("Schnorr", r, pubKeyX, pubKeyY, msgHash));
        uint256 e = uint256(challenge) % EllipticCurve.N;

        EllipticCurve.Point memory G = EllipticCurve.Point(EllipticCurve.GX, EllipticCurve.GY);
        EllipticCurve.Point memory Q = EllipticCurve.Point(pubKeyX, pubKeyY);

        EllipticCurve.Point memory sG = EllipticCurve.scalarMul(G, s);
        EllipticCurve.Point memory eQ = EllipticCurve.scalarMul(Q, e);

        EllipticCurve.Point memory negEQ = EllipticCurve.Point(eQ.x, EllipticCurve.P - eQ.y);
        EllipticCurve.Point memory recoveredR = EllipticCurve.pointAdd(sG, negEQ);

        return recoveredR.x == r;
    }

    function crossTenantVerify(
        uint256 sourceTenantId,
        uint256 targetTenantId,
        bytes32 keyId,
        bytes32 messageHash,
        uint256 r,
        uint256 s,
        uint256 pubKeyX,
        uint256 pubKeyY
    ) external returns (bool) {
        TenantKeySlot storage sourceSlot = _tenantKeys[sourceTenantId][keyId];
        require(sourceSlot.active, "Source key not active");
        require(block.timestamp < sourceSlot.expiresAt, "Source key expired");

        // Cross-tenant isolation: verify key belongs to source tenant with tenant ID binding
        bytes32 computedHash = keccak256(abi.encode(sourceTenantId, pubKeyX, pubKeyY, sourceSlot.keyType));
        require(computedHash == sourceSlot.keyHash, "Key mismatch");

        // Require explicit admin authorization for cross-tenant operations
        require(_tenantAdmins[targetTenantId] == msg.sender, "Not target tenant admin");

        VerificationContext memory ctx = VerificationContext({
            tenantId: targetTenantId,
            messageHash: messageHash,
            sigType: sourceSlot.keyType
        });

        bool valid = _dispatchVerification(ctx, r, s, pubKeyX, pubKeyY);
        if (valid) {
            _tenantNonces[targetTenantId]++;
            emit SignatureVerified(targetTenantId, messageHash);
        }
        return valid;
    }
}
